assert len(items) == 100, f"Expected 100 items, got {len(items)}"
for i, it in enumerate(items):
    it["ipa"] = it["ipa"].strip()
    assert len(it["vi"]) <= 35, f"VI too long ({len(it['vi'])}) at {i}: {it['vi']}"
    assert it["ipa"] == "" or (it["ipa"].startswith("/") and it["ipa"].endswith("/")), f"Invalid IPA at {i}: {it['ipa']}"
    assert it["pos"] in ["noun", "verb", "adj", "adv", "phrase", "intj", "prep", "conj", "pron", "det", "num"]

